fun linearSearch(nums: IntArray, target: Int): Int? {
    for (i in nums.indices) {
        if (nums[i] == target) return i
    }
    return null
}

fun binarySearch(nums: IntArray, target: Int): Int? {
    var low = 0
    var high = nums.size - 1
    while (low <= high) {
        val mid = low + (high - low) / 2
        when {
            nums[mid] == target -> return mid
            nums[mid] < target -> low = mid + 1
            else -> high = mid - 1
        }
    }
    return null
}

fun bubbleSort(nums: IntArray) {
    for (pass in 0 until nums.size - 1) {
        var swapped = false
        for (i in 0 until nums.size - 1 - pass) {
            if (nums[i] > nums[i + 1]) {
                val temp = nums[i]
                nums[i] = nums[i + 1]
                nums[i + 1] = temp
                swapped = true
            }
        }
        if (!swapped) return
    }
}

fun selectionSort(nums: IntArray) {
    for (i in 0 until nums.size - 1) {
        var minIndex = i
        for (j in i + 1 until nums.size) {
            if (nums[j] < nums[minIndex]) {
                minIndex = j
            }
        }
        val temp = nums[i]
        nums[i] = nums[minIndex]
        nums[minIndex] = temp
    }
}

fun insertionSort(nums: IntArray) {
    for (i in 1 until nums.size) {
        val current = nums[i]
        var j = i - 1
        while (j >= 0 && nums[j] > current) {
            nums[j + 1] = nums[j]
            j--
        }
        nums[j + 1] = current
    }
}

fun mergeSort(nums: IntArray): IntArray {
    if (nums.size <= 1) {
        return nums.copyOf()
    }
    val mid = nums.size / 2
    val left = mergeSort(nums.copyOfRange(0, mid))
    val right = mergeSort(nums.copyOfRange(mid, nums.size))
    return merge(left, right)
}

private fun merge(left: IntArray, right: IntArray): IntArray {
    val result = IntArray(left.size + right.size)
    var i = 0
    var j = 0
    while (i < left.size || j < right.size) {
        if (j >= right.size || (i < left.size && left[i] <= right[j])) {
            result[i + j] = left[i]
            i++
        } else {
            result[i + j] = right[j]
            j++
        }
    }
    return result
}

fun quickSort(nums: IntArray) {
    quickSort(nums, 0, nums.size - 1)
}

private fun quickSort(nums: IntArray, low: Int, high: Int) {
    if (low >= high) {
        return
    }
    val pivotIndex = partition(nums, low, high)
    quickSort(nums, low, pivotIndex - 1)
    quickSort(nums, pivotIndex + 1, high)
}

private fun partition(nums: IntArray, low: Int, high: Int): Int {
    val pivot = nums[high]
    var i = low - 1
    for (j in low until high) {
        if (nums[j] <= pivot) {
            i++
            val temp = nums[i]
            nums[i] = nums[j]
            nums[j] = temp
        }
    }
    val temp = nums[i + 1]
    nums[i + 1] = nums[high]
    nums[high] = temp
    return i + 1
}

fun heapSort(nums: IntArray) {
    for (i in nums.size / 2 - 1 downTo 0) {
        siftDown(nums, i, nums.size)
    }
    for (end in nums.size - 1 downTo 1) {
        val temp = nums[0]
        nums[0] = nums[end]
        nums[end] = temp
        siftDown(nums, 0, end)
    }
}

private fun siftDown(nums: IntArray, root: Int, end: Int) {
    var current = root
    while (current * 2 + 1 < end) {
        var child = current * 2 + 1
        if (child + 1 < end && nums[child + 1] > nums[child]) {
            child++
        }
        if (nums[current] >= nums[child]) {
            return
        }
        val temp = nums[current]
        nums[current] = nums[child]
        nums[child] = temp
        current = child
    }
}

class Graph {
    private val edges = mutableMapOf<String, MutableList<String>>()

    fun addEdge(from: String, to: String) {
        edges.getOrPut(from) { mutableListOf() }.add(to)
        edges.getOrPut(to) { mutableListOf() }.add(from)
    }

    fun neighbors(node: String): List<String> = edges[node].orEmpty()
}

fun bfs(graph: Graph, start: String): List<String> {
    val order = mutableListOf<String>()
    val visited = mutableSetOf(start)
    val queue = ArrayDeque<String>()
    queue.addLast(start)
    while (queue.isNotEmpty()) {
        val node = queue.removeFirst()
        order.add(node)
        for (neighbor in graph.neighbors(node)) {
            if (visited.add(neighbor)) {
                queue.addLast(neighbor)
            }
        }
    }
    return order
}

fun dfs(graph: Graph, start: String): List<String> {
    val order = mutableListOf<String>()
    visit(graph, start, mutableSetOf(), order)
    return order
}

private fun visit(
    graph: Graph,
    node: String,
    visited: MutableSet<String>,
    order: MutableList<String>,
) {
    if (!visited.add(node)) {
        return
    }
    order.add(node)
    for (neighbor in graph.neighbors(node)) {
        visit(graph, neighbor, visited, order)
    }
}

class WeightedGraph {
    data class Edge(val to: String, val weight: Int)

    private val edges = mutableMapOf<String, MutableList<Edge>>()

    fun addEdge(from: String, to: String, weight: Int) {
        edges.getOrPut(from) { mutableListOf() }.add(Edge(to, weight))
        edges.getOrPut(to) { mutableListOf() }.add(Edge(from, weight))
    }

    fun neighbors(node: String): List<Edge> = edges[node].orEmpty()
}

fun dijkstra(graph: WeightedGraph, start: String): Map<String, Long> {
    val distances = mutableMapOf(start to 0L)
    val visited = mutableSetOf<String>()
    while (true) {
        val node = distances.filterKeys { it !in visited }.minByOrNull { it.value }?.key ?: break
        visited.add(node)
        val current = distances.getValue(node)
        for (edge in graph.neighbors(node)) {
            val candidate = current + edge.weight
            if (candidate < distances.getOrDefault(edge.to, Long.MAX_VALUE)) {
                distances[edge.to] = candidate
            }
        }
    }
    return distances
}

