fun describe(result: Result<Int>): String {
    if (result.isSuccess) {
        return "ok ${result.getOrNull()}"
    }
    return when (result.exceptionOrNull()) {
        is NumberFormatException -> "not a number"
        is IllegalArgumentException -> "not positive"
        else -> "unknown"
    }
}

